// Aplatit la sortie NocoDB v3 {id, fields:{}} au format plat du noeud
// Airtable historique : {...champs, id} -> aucune expression aval a changer.
return $input.all().map(i => ({ json: { ...(i.json.fields || {}), id: i.json.id } }));

// runOnceForEachItem : $json = current row from "Cours en Production"
const row = $json;

// Parse module/lesson info from Sheets columns
// Module format: "M1: Titre du module"
// Lecon format: "L1: Titre de la lecon"
const moduleMatch = (row.Module || '').match(/^M(\d+):\s*(.+)$/);
const lessonMatch = (row.Lecon || '').match(/^L(\d+):\s*(.+)$/);

const moduleNumber = moduleMatch ? parseInt(moduleMatch[1]) : 1;
const moduleTitle = moduleMatch ? moduleMatch[2].trim() : (row.Module || 'Module');
const lessonNumber = lessonMatch ? parseInt(lessonMatch[1]) : 1;
const lessonTitle = lessonMatch ? lessonMatch[2].trim() : (row.Lecon || 'Lecon');

// Parse duration (e.g., "10 min" -> 10)
const durationMatch = (row.Duree || '10 min').match(/(\d+)/);
const durationMinutes = durationMatch ? parseInt(durationMatch[1]) : 10;

return {
  json: {
    id: row.id,
    course_title: row.Cours || '',
    module_title: moduleTitle,
    module_number: moduleNumber,
    lesson_title: lessonTitle,
    lesson_number: lessonNumber,
    lesson_type: row.Type || 'text',
    duration_minutes: durationMinutes,
    // Pass through for Sheets update
    original_module: row.Module || '',
    original_lecon: row.Lecon || ''
  }
};

// runOnceForEachItem
const response = $input.item.json;
const allBuildData = $('Build — Payload lecon (par ligne)').all();
const buildData = allBuildData[$itemIndex]?.json || {};

let lesson;
try {
  let text = '';
  if (response.content?.parts) {
    text = response.content.parts.map(p => p.text || '').join('');
  } else if (response.lesson) {
    lesson = response;
  } else if (typeof response === 'string') {
    text = response;
  } else {
    text = JSON.stringify(response);
  }

  if (!lesson && text) {
    let cleaned = text.trim();
    cleaned = cleaned.replace(/^```(?:json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '').trim();
    cleaned = cleaned.replace(/,\s*([\}\]])/g, '$1');

    try { lesson = JSON.parse(cleaned); } catch(e1) {}

    if (!lesson) {
      const match = cleaned.match(/\{[\s\S]+\}/);
      if (match) {
        let block = match[0].replace(/,\s*([\}\]])/g, '$1');
        try { lesson = JSON.parse(block); } catch(e2) {}
      }
    }
  }
} catch (e) {
  // Fallback graceful
}

if (!lesson) {
  return {
    json: {
      id: buildData.id,
      course_title: buildData.course_title || '',
      module_title: buildData.module_title || '',
      lesson_title: buildData.lesson_title || '',
      content_html: '',
      word_count: 0,
      reading_time_minutes: 0,
      key_points: [],
      practical_tip: '',
      takeaway: '',
      _parse_failed: true
    }
  };
}

const lessonData = lesson.lesson || lesson;

return {
  json: {
    id: buildData.id,
    course_title: buildData.course_title,
    module_title: buildData.module_title,
    lesson_title: lessonData.title || buildData.lesson_title,
    content_html: lessonData.content_html || '',
    word_count: lessonData.word_count || 0,
    reading_time_minutes: lessonData.reading_time_minutes || 0,
    key_points: lessonData.key_points || [],
    practical_tip: lessonData.practical_tip || '',
    takeaway: lessonData.takeaway || ''
  }
};

